cases.source:
name: Synthetic functions
on: {tool_result: null, window: 2}
decisions:
  review:
    input:
      equal: ${{ strictEquals(message.kind, 'tool_result') }}
      member: ${{ contains(session.requests.*.kind, 'user_message') }}
      prefix: ${{ startsWith(message.kind, 'tool') }}
      suffix: ${{ endsWith(message.kind, 'result') }}
      joined: ${{ join(session.requests.*.text, '; ') }}
      formatted: "${{ format('Kind: {0}', message.kind) }}"
      serialized: ${{ toJSON(message.tool.result) }}
      parsed: ${{ fromJSON('null') }}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic unknown function
on: {tool_result: null}
decisions:
  review:
    input: {value: "${{ unknownFunction(message.kind) }}"}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic fixed question
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: "${{ format('Kind: {0}', message.kind) }}", criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic dynamic key
on: {tool_result: null}
decisions:
  review:
    input: {value: "${{ message.tool.arguments[message.kind] }}"}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic dynamic index
on: {tool_result: null, window: 2}
decisions:
