    input:
      value: {nested: ["Kind: ${{ message.kind }}", "${{ format('Status: {0}', message.tool.result.status) }}"]}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
