    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic missing map value
on: {tool_result: null}
decisions:
  review:
    input:
      value: {map: '${{ session.requests }}', as: outer, value: {map: '${{ session.requests }}', as: inner}}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic extra map key
on: {tool_result: null}
decisions:
  review:
    input: {value: {map: '${{ session.requests }}', as: item, value: '${{ item.text }}', extra: true}}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic invalid alias
on: {tool_result: null}
decisions:
  review:
    input: {value: {map: '${{ session.requests }}', as: Invalid, value: true}}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic map collection wrapper
on: {tool_result: null}
decisions:
  review:
    input: {value: {map: 'Items: ${{ session.requests }}', as: item, value: true}}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic dynamic status
on: {tool_result: null}
decisions:
  review:
    input: {value: '${{ message.kind }}'}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions:
  - type: status
    input:
      result: ${{ decisions.review.outputs.verdict == 'yes' && 'success' || 'failure' }}
      message: "Selected: ${{ decisions.review.outputs.verdict }}"

name: Synthetic whole message
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions:
  - type: status
    input: {result: success, message: "${{ format('Selected: {0}', decisions.review.outputs.verdict) }}"}

name: Synthetic embedded status
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: "Result: ${{ 'success' }}"}}]

name: Synthetic message type
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success, message: {text: example}}}]

name: Synthetic blank message
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success, message: '   '}}]

name: Synthetic blank expression
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: '${{ }}'}}]

name: Synthetic root budget
budget: {steps: 10000}
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic decision budget
on: {tool_result: null}
decisions:
  review:
    budget: {steps: 10000}
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic local check
on: {tool_result: null}
actions: [{type: status, input: {result: success}}]

name: Synthetic local no write
on: {tool_result: null}
actions: [{type: status, if: false, input: {result: success}}]

name: Synthetic empty decisions
on: {tool_result: null}
decisions: {}
actions: [{type: status, input: {result: success}}]

name: Synthetic undeclared local decision condition
on: {tool_result: null}
actions:
  - type: status
    if: false && decisions.review.outputs.verdict == 'yes'
    input: {result: success}

name: Synthetic undeclared local decision message
on: {tool_result: null}
actions:
  - type: status
    if: false
    input: {result: success, message: 'Selected: ${{ decisions.review.outputs.verdict }}'}

name: Synthetic multiple decisions
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
  other:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic multiple questions
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
      other: {type: choice, question: Is this clear?, criteria: {yes: Clear., no: Not clear.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic Score
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: score, question: Is this useful?, criteria: [Weak., Strong.]}
actions: [{type: status, input: {result: success}}]

name: Synthetic Noul
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: noul, question: Is this useful?}
actions: [{type: status, input: {result: success}}]

name: Synthetic mixed questions
on: {tool_result: null}
decisions:
  review:
    input: {result: '${{ message.tool.result }}'}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
      severity: {type: score, question: How severe is the result?, criteria: [Low., Medium., High.]}
      applies: {type: noul, question: Does this result need review?}
actions:
  - type: status
    if: decisions.review.outputs.verdict == 'yes' && decisions.review.outputs.severity >= 1 && decisions.review.outputs.applies >= 0.95
    input: {result: failure}

