      a: {type: noul, question: Is A present?}
      b: {type: noul, question: Is B present?}
      c: {type: noul, question: Is C present?}
      d: {type: noul, question: Is D present?}
      e: {type: noul, question: Is E present?}
      f: {type: noul, question: Is F present?}
      g: {type: noul, question: Is G present?}
      h: {type: noul, question: Is H present?}
actions: [{type: status, input: {result: success}}]

name: Synthetic nine questions
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      a: {type: noul, question: Is A present?}
      b: {type: noul, question: Is B present?}
      c: {type: noul, question: Is C present?}
      d: {type: noul, question: Is D present?}
      e: {type: noul, question: Is E present?}
      f: {type: noul, question: Is F present?}
      g: {type: noul, question: Is G present?}
      h: {type: noul, question: Is H present?}
      i: {type: noul, question: Is I present?}
actions: [{type: status, input: {result: success}}]

name: Synthetic nine independent blocks
on: {tool_result: null}
decisions:
  a: {input: {value: true}, output: {answer: {type: noul, question: Is A present?}}}
  b: {input: {value: true}, output: {answer: {type: noul, question: Is B present?}}}
  c: {input: {value: true}, output: {answer: {type: noul, question: Is C present?}}}
  d: {input: {value: true}, output: {answer: {type: noul, question: Is D present?}}}
  e: {input: {value: true}, output: {answer: {type: noul, question: Is E present?}}}
  f: {input: {value: true}, output: {answer: {type: noul, question: Is F present?}}}
  g: {input: {value: true}, output: {answer: {type: noul, question: Is G present?}}}
  h: {input: {value: true}, output: {answer: {type: noul, question: Is H present?}}}
  i: {input: {value: true}, output: {answer: {type: noul, question: Is I present?}}}
actions: [{type: status, input: {result: success}}]

name: Synthetic Score details
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      severity: {type: score, question: How severe is the result?, criteria: [Low., Medium., High.]}
actions:
  - type: status
    if: decisions.review.details.severity.probabilities[0] >= 0.5 && decisions.review.details.severity.confidence >= 0.8
    input: {result: success}

name: Synthetic Choice details
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: Useful., no: Not useful.}}
actions:
  - type: status
    if: decisions.review.details.verdict.probabilities.yes >= 0.95 && decisions.review.details.verdict.confidence >= 0.8
    input: {result: success}

name: Synthetic whole details
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      severity: {type: score, question: How severe is the result?, criteria: [Low., High.]}
actions:
  - type: status
    input: {result: success, message: '${{ toJSON(decisions.review.details) }}'}

name: Synthetic Noul empty details
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      applies: {type: noul, question: Does this apply?}
actions:
  - type: status
    input: {result: success, message: '${{ toJSON(decisions.review.details.applies) }}'}

name: Synthetic invalid Noul confidence
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      applies: {type: noul, question: Does this apply?}
actions:
  - type: status
    if: false && decisions.review.details.applies.confidence >= 0.9
    input: {result: success}

name: Synthetic invalid Noul probabilities
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      applies: {type: noul, question: Does this apply?}
actions:
  - type: status
    input: {result: success, message: '${{ toJSON(decisions.review.details.applies.probabilities) }}'}

name: Synthetic invalid Score label key
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      severity: {type: score, question: How severe is the result?, criteria: [Low., High.]}
actions:
  - type: status
    if: decisions.review.details.severity.probabilities.low >= 0.9
    input: {result: success}

name: Synthetic invalid Score legend
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      severity: {type: score, question: How severe is the result?, criteria: [Low., High.]}
actions:
  - type: status
    input: {result: success, message: '${{ toJSON(decisions.review.details.severity.legend) }}'}

name: Synthetic duplicate output
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      answer: {type: noul, question: Is A present?}
      answer: {type: noul, question: Is B present?}
actions: [{type: status, input: {result: success}}]

name: Synthetic Noul criteria
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      applies: {type: noul, question: Does this apply?, criteria: [No., Yes.]}
actions: [{type: status, input: {result: success}}]

name: Synthetic nonstring Choice criterion
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      verdict: {type: choice, question: Is this useful?, criteria: {yes: true, no: Not useful.}}
actions: [{type: status, input: {result: success}}]

name: Synthetic nonstring Score criterion
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      severity: {type: score, question: How severe is the result?, criteria: [Low., 1]}
actions: [{type: status, input: {result: success}}]

name: Synthetic one Score criterion
on: {tool_result: null}
decisions:
  review:
    input: {value: true}
    output:
      severity: {type: score, question: How severe is the result?, criteria: [Low.]}
actions: [{type: status, input: {result: success}}]

name: Synthetic self dependency
on: {tool_result: null}
decisions:
  review:
    input: {value: '${{ decisions.review.outputs.applies }}'}
    output:
      applies: {type: noul, question: Does this apply?}
actions: [{type: status, input: {result: success}}]

name: Synthetic sibling dependency
on: {tool_result: null}
decisions:
  first:
    input: {value: true}
    output: {applies: {type: noul, question: Does this apply?}}
  second:
    input: {value: '${{ toJSON(decisions.first) }}'}
    output: {applies: {type: noul, question: Does this still apply?}}
actions: [{type: status, input: {result: success}}]

name: Synthetic unsupported inventory
on: {tool_result: null}
if: false
decisions:
  review:
    input: {value: '${{ repo.instructions }}'}
    output: {applies: {type: noul, question: Does this apply?}}
actions: [{type: status, input: {result: success}}]

name: Synthetic unsupported message action
on: {tool_result: null}
if: false
decisions:
  review:
    input: {value: true}
    output: {applies: {type: noul, question: Does this apply?}}
actions: [{type: message, if: false, input: {message: Review this result.}}]

name: Synthetic unsupported model filter
on: {tool_result: {models: [provider/observed-model]}}
if: false
decisions:
  review:
    input: {value: true}
    output: {applies: {type: noul, question: Does this apply?}}
actions: [{type: status, input: {result: success}}]

name: Synthetic invalid path glob
on: {tool_result: {paths: ['src/pre**fix']}}
actions: [{type: status, input: {result: success}}]

name: Synthetic parent path glob
on: {tool_result: {paths: ['../outside/**']}}
actions: [{type: status, input: {result: success}}]

name: Synthetic recorded requester
on: {tool_result: null}
decisions:
  review:
    input:
      model: ${{ message.model }}
      fast_mode: ${{ message.fast_mode }}
      paths: ${{ message.tool.paths }}
    output: {applies: {type: noul, question: Does this apply?}}
actions: [{type: status, input: {result: success}}]

name: Synthetic configured descriptions
on: {tool_result: null}
decisions:
  review:
    input:
      descriptions: ${{ repo.skills.*.description }}
      global_paths: ${{ global.skills.*.path }}
    output: {applies: {type: noul, question: Does this apply?}}
actions: [{type: status, input: {result: success}}]

name: Synthetic unsupported activity partition
on: {tool_result: null}
if: false
decisions:
  review:
    input: {value: '${{ session.last_activity_period }}'}
    output: {applies: {type: noul, question: Does this apply?}}
actions: [{type: status, input: {result: success}}]

name: Synthetic unsupported trigger
on: {session_idle: null}
if: false
decisions:
  review:
    input: {value: true}
    output: {applies: {type: noul, question: Does this apply?}}
actions: [{type: status, input: {result: success}}]
